// Read the two dashboard Inputs bound to this part, keyed by each element's own
// label (Root Properties). Neither is carried in via a connector -- ctx.ui is a
// completely separate channel, unrelated to ctx.inputs.
const basePrice = ctx.ui.UINumericInput['Base Price'] || 0;
const code = (ctx.ui.UITextInput['Discount Code'] || '').trim().toUpperCase();

let discount = 0, status;
if (!code) {
  status = 'No discount code entered';
} else if (code === 'SAVE10') {
  discount = 0.1;
  status = 'Discount applied (' + code + ')';
} else {
  status = 'Unknown code: ' + code;
}
const total = Math.round(basePrice * (1 - discount) * 100) / 100;
ctx.log('Base ' + basePrice + ', code "' + code + '" -> total ' + total);

// Write the two dashboard Outputs bound to this part, keyed the same way by their
// own label -- picked up as each one's own badge the moment this tick commits. A
// label with no bound element at all would just be silently ignored.
ctx.ui.UINumericOutput['Total Cost'] = total;
ctx.ui.UITextOutput['Status'] = status;

return { value: total, state: {} };
